import { useState } from 'react';
import {
  Button,
  Drawer,
  DrawerHeader,
  DrawerTitle,
  DrawerCloseButton,
  DrawerBody,
  Nav,
  NavItem,
  NavDivider,
  IconMenu,
  IconLogOut,
} from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface NavigationDrawerProps {
  onNavigate: (key: NavKey) => void;
}

export default function NavigationDrawer({ onNavigate }: NavigationDrawerProps) {
  const [isOpen, setIsOpen] = useState(false);

  const handleSelect = (key: NavKey) => {
    onNavigate(key);
    setIsOpen(false);
  };

  return (
    <>
      <Button
        variant="secondary"
        iconStart={<IconMenu />}
        onClick={() => setIsOpen(true)}
      >
        Меню
      </Button>

      <Drawer
        placement="left"
        isOpen={isOpen}
        onClose={() => setIsOpen(false)}
      >
        <DrawerHeader>
          <DrawerTitle>Навигация</DrawerTitle>
          <DrawerCloseButton onClick={() => setIsOpen(false)} />
        </DrawerHeader>
        <DrawerBody>
          <Nav>
            <NavItem onSelect={() => handleSelect('projects')}>
              Проекты
            </NavItem>
            <NavItem onSelect={() => handleSelect('team')}>
              Команда
            </NavItem>
            <NavItem onSelect={() => handleSelect('settings')}>
              Настройки
            </NavItem>
            <NavDivider />
            <NavItem
              danger
              iconStart={<IconLogOut />}
              onSelect={() => handleSelect('logout')}
            >
              Выйти
            </NavItem>
          </Nav>
        </DrawerBody>
      </Drawer>
    </>
  );
}

